    recipes_list: {
        parameters: {
            query?: {
                /** @description Recipes with any of these courses, by slug. Unknown slugs are dropped; with none left, nothing is filtered. */
                course?: string[];
                /** @description Recipes with any of these cuisines, by slug. Unknown slugs are dropped; with none left, nothing is filtered. */
                cuisine?: string[];
                /** @description Recipes with every one of these diet tags, worked out as each recipe's diet_tags are. Any other value is a 400. */
                diet?: ("vegetarian" | "vegan" | "gluten_free" | "dairy_free")[];
                /** @description Recipes with any of these difficulties. Any other value is a 400. */
                difficulty?: ("easy" | "medium" | "hard")[];
                /** @description Recipes with no line, optional or not, using any of these ingredients, by slug. Unknown slugs exclude nothing. */
                exclude_ingredient?: string[];
                /** @description Recipes with a line, optional or not, using any of these ingredients (every one with include_match=all), by slug. Unknown slugs are dropped; with none left, nothing is filtered. */
                include_ingredient?: string[];
                /**
                 * @description any (or missing) means a recipe needs one of the include_ingredient ingredients; all means it needs every one of them. Any other value is a 400.
                 *
                 *     * `any` - any
                 *     * `all` - all
                 */
                include_match?: "any" | "all";
                /** @description Cook time is this many minutes or fewer. A value that is not a whole number of at least 1 is a 400. */
                max_cook?: number;
                /** @description Prep time is this many minutes or fewer. A value that is not a whole number of at least 1 is a 400. */
                max_prep?: number;
                /** @description Prep plus cook plus extra time is this many minutes or fewer. A value that is not a whole number of at least 1 is a 400. */
                max_total?: number;
                /** @description true means only one-pot recipes; false or missing means every recipe. */
                one_pot?: boolean;
                /** @description Title, description, an ingredient's name or synonym, or a cuisine contains this text, ignoring case and accents. Title matches come first, then the others, alphabetically within each. */
                q?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["RecipeSummary"][];
                };
            };
            /** @description A difficulty, a diet, an include_match or a time limit is not one the list accepts. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
